func TestComponentFormTypingReachesTheFocusedInput(t *testing.T) {
	f := typeInto(NewComponentForm(nil), "api")
	if f.nameInput.Value() != "api" {
		t.Errorf("name input = %q after typing on field 0, want \"api\"", f.nameInput.Value())
	}

