func TestSelectionStyleFollowsTheContainerState(t *testing.T) {
	m := loadedModel(t) // cursor on api, which is exited

	errorStyle := m.containerTable.Styles().Selected

	m = feed(t, m, testutil.Key("down")) // cache, paused
	if m.containerTable.Styles().Selected.GetBackground() == errorStyle.GetBackground() {
		t.Error("the selection style stayed on the error colour after moving to a paused container")
	}

