1	package dashboard
2	
3	import (
4		"fmt"
5		"os"
6		"os/exec"
7		"path/filepath"
8		"runtime"
9		"strings"
10		"time"
11	
12		tea "github.com/charmbracelet/bubbletea"
13	
14		"github.com/anthnel/devdesk/internal/config"
15		"github.com/anthnel/devdesk/internal/docker"
16		gitlabpkg "github.com/anthnel/devdesk/internal/gitlab"
17		"github.com/anthnel/devdesk/internal/scan"
18		"github.com/anthnel/devdesk/internal/shared"
19		"github.com/anthnel/devdesk/internal/status"
20	)
21	
22	// Messages
23	
24	// StatusCheckMsg contains results from a background status check
25	type StatusCheckMsg struct {
26		Result status.MonitorResult
27	}
28	
29	// GitLabStatsMsg contains fetched GitLab statistics
30	type GitLabStatsMsg struct {
31		Stats shared.GitLabStats
32	}
33	
34	// DockerStatsMsg contains fetched Docker statistics
35	type DockerStatsMsg struct {
36		Stats shared.DockerStats
37	}
38	
39	// OCIStatsMsg contains fetched OCI resource statistics
40	type OCIStatsMsg struct {
41		Stats shared.OCIStats
42	}
43	
44	// WorkspaceStatsMsg contains workspace count and disk usage
45	type WorkspaceStatsMsg struct {
46		Count    int
47		DiskSize string
48	}
49	
50	// ToolsDetectedMsg contains detected tool information
51	type ToolsDetectedMsg struct {
52		Tools []shared.ToolInfo
53	}
54	
55	// RefreshTickMsg triggers a periodic refresh
56	type RefreshTickMsg time.Time
57	
58	// Model represents the dashboard view state
59	type Model struct {
60		config *config.Config
61		shared *shared.State
62		width  int
63		height int
64	
65		// Data
66		serviceComponents []status.ComponentStatus
67		serviceStatus     shared.ServiceGlobalStatus
68		gitlabStats       *shared.GitLabStats
69		dockerStats       *shared.DockerStats
70		ociStats          *shared.OCIStats
71		tools             []shared.ToolInfo
72		workspaceCount    int
73		workspaceDisk     string
74	
75		// Loading flags
76		loadingServices   bool
77		loadingGitLab     bool
78		loadingDocker     bool
79		loadingOCI        bool
80		loadingWorkspaces bool
81		loadingTools      bool
82	
83		// Refresh
84		refreshInterval time.Duration
85		lastRefresh     time.Time
86	}
87	
88	// New creates a new dashboard model
89	func New(cfg *config.Config, state *shared.State) Model {
90		return Model{
91			config:            cfg,
92			shared:            state,
93			serviceStatus:     shared.ServiceStatusUnknown,
94			loadingServices:   true,
95			loadingGitLab:     true,
96			loadingDocker:     true,
97			loadingOCI:        true,
98			loadingWorkspaces: true,
99			loadingTools:      true,
100			refreshInterval:   time.Duration(cfg.Status.RefreshInterval) * time.Second,
101		}
102	}
103	
104	// Init initializes the dashboard by loading all data
105	func (m Model) Init() tea.Cmd {
106		return tea.Batch(
107			m.checkServices(),
108			m.fetchGitLabStats(),
109			m.fetchDockerStats(),
110			m.fetchOCIStats(),
111			m.fetchWorkspaceStats(),
112			m.detectTools(),
113			m.scheduleRefresh(),
114		)
115	}
116	
117	// Update handles messages
118	func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
119		switch msg := msg.(type) {
120		case tea.WindowSizeMsg:
121			m.width = msg.Width
122			m.height = msg.Height
123	
124		case tea.KeyMsg:
125			return m.handleKeyMsg(msg)
126	
127		case StatusCheckMsg:
128			return m.handleStatusCheck(msg)
129	
130		case GitLabStatsMsg:
131			return m.handleGitLabStats(msg)
132	
133		case DockerStatsMsg:
134			return m.handleDockerStats(msg)
135	
136		case OCIStatsMsg:
137			return m.handleOCIStats(msg)
138	
139		case WorkspaceStatsMsg:
140			return m.handleWorkspaceStats(msg)
141	
142		case ToolsDetectedMsg:
143			return m.handleToolsDetected(msg)
144	
145		case RefreshTickMsg:
146			return m, m.refreshAll()
147		}
148	
149		return m, nil
150	}
151	
152	// handleKeyMsg processes keyboard input
153	func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
154		switch msg.String() {
155		case "ctrl+r":
156			m.loadingServices = true
157			m.loadingGitLab = true
158			m.loadingDocker = true
159			m.loadingOCI = true
160			m.loadingWorkspaces = true
161			return m, m.refreshAll()
162		case "m":
163			return m, openURL(fmt.Sprintf("%s/dashboard/merge_requests", m.config.GitLab.URL))
164		case "i":
165			if m.shared.CurrentUser != nil {
166				return m, openURL(fmt.Sprintf("%s/dashboard/issues?sort=created_date&state=opened&assignee_username[]=%s", m.config.GitLab.URL, m.shared.CurrentUser.Username))
167			}
168		}
169		return m, nil
170	}
171	
172	// handleStatusCheck processes status check results
173	func (m Model) handleStatusCheck(msg StatusCheckMsg) (tea.Model, tea.Cmd) {
174		m.loadingServices = false
175		m.serviceComponents = msg.Result.Components
176		m.lastRefresh = msg.Result.Timestamp
177	
178		m.serviceStatus = computeGlobalStatus(m.serviceComponents)
179	
180		m.shared.ServiceStatus = m.serviceStatus
181		m.shared.ServiceComponents = m.serviceComponents
182	
183		return m, nil
184	}
185	
186	// handleGitLabStats processes GitLab stats results
187	func (m Model) handleGitLabStats(msg GitLabStatsMsg) (tea.Model, tea.Cmd) {
188		m.loadingGitLab = false
189		m.gitlabStats = &msg.Stats
190		m.shared.GitLabStats = &msg.Stats
191		return m, nil
192	}
193	
194	// handleDockerStats processes Docker stats results
195	func (m Model) handleDockerStats(msg DockerStatsMsg) (tea.Model, tea.Cmd) {
196		m.loadingDocker = false
197		m.dockerStats = &msg.Stats
198		m.shared.DockerStats = &msg.Stats
199		return m, nil
200	}
201	
202	// handleOCIStats processes OCI stats results
203	func (m Model) handleOCIStats(msg OCIStatsMsg) (tea.Model, tea.Cmd) {
204		m.loadingOCI = false
205		m.ociStats = &msg.Stats
206		m.shared.OCIStats = &msg.Stats
207		return m, nil
208	}
209	
210	// handleWorkspaceStats processes workspace stats results
211	func (m Model) handleWorkspaceStats(msg WorkspaceStatsMsg) (tea.Model, tea.Cmd) {
212		m.loadingWorkspaces = false
213		m.workspaceCount = msg.Count
214		m.workspaceDisk = msg.DiskSize
215		m.shared.WorkspaceCount = msg.Count
216		return m, nil
217	}
218	
219	// handleToolsDetected processes tool detection results
220	func (m Model) handleToolsDetected(msg ToolsDetectedMsg) (tea.Model, tea.Cmd) {
221		m.loadingTools = false
222		m.tools = msg.Tools
223		m.shared.Tools = msg.Tools
224		return m, nil
225	}
226	
227	// Commands
228	
229	func (m Model) checkServices() tea.Cmd {
230		cfg := m.config
231		return func() tea.Msg {
232			result := status.RunCheck(cfg)
233			return StatusCheckMsg{Result: result}
234		}
235	}
236	
237	func (m Model) fetchGitLabStats() tea.Cmd {
238		client := m.shared.GitLabClient
239		user := m.shared.CurrentUser
240	
241		if client == nil || user == nil {
242			return func() tea.Msg {
243				return GitLabStatsMsg{Stats: shared.GitLabStats{}}
244			}
245		}
246	
247		userID := user.ID
248		return func() tea.Msg {
249			stats := gitlabpkg.FetchDashboardStats(client, userID)
250			return GitLabStatsMsg{Stats: shared.GitLabStats{
251				AssignedMRs:    stats.AssignedMRs,
252				ReviewMRs:      stats.ReviewMRs,
253				AssignedIssues: stats.AssignedIssues,
254				TotalProjects:  stats.TotalProjects,
255				TotalGroups:    stats.TotalGroups,
256			}}
257		}
258	}
259	
260	func (m Model) fetchDockerStats() tea.Cmd {
261		return func() tea.Msg {
262			stats := docker.FetchContainerStats()
263			return DockerStatsMsg{Stats: shared.DockerStats{
264				Available: stats.Available,
265				Running:   stats.Running,
266				Stopped:   stats.Stopped,
267				Paused:    stats.Paused,
268			}}
269		}
270	}
271	
272	func (m Model) fetchOCIStats() tea.Cmd {
273		return func() tea.Msg {
274			stats := docker.FetchOCIStats()
275			return OCIStatsMsg{Stats: shared.OCIStats{
276				Available:       stats.Available,
277				ImagesCount:     stats.ImagesCount,
278				ImagesSize:      stats.ImagesSize,
279				ContainersCount: stats.ContainersCount,
280				ContainersSize:  stats.ContainersSize,
281				VolumesCount:    stats.VolumesCount,
282				VolumesSize:     stats.VolumesSize,
283			}}
284		}
285	}
286	
287	func (m Model) fetchWorkspaceStats() tea.Cmd {
288		workspacesDir := m.config.App.WorkspacesDir
289		return func() tea.Msg {
290			dir := workspacesDir
291			if len(dir) >= 2 && dir[:2] == "~/" {
292				home, _ := os.UserHomeDir()
293				dir = filepath.Join(home, dir[2:])
294			}
295	
296			entries, err := os.ReadDir(dir)
297			count := 0
298			if err == nil {
299				for _, e := range entries {
300					if e.IsDir() {
301						count++
302					}
303				}
304			}
305	
306			diskSize := calculateDiskUsage(dir)
307	
308			return WorkspaceStatsMsg{Count: count, DiskSize: diskSize}
309		}
310	}
311	
312	func (m Model) detectTools() tea.Cmd {
313		cfg := m.config
314		return func() tea.Msg {
315			var tools []shared.ToolInfo
316	
317			// Docker
318			tools = append(tools, detectBinaryTool("Docker", "docker", "version", "--format", "{{.Client.Version}}"))
319	
320			// Security tools via scan.CheckDependencies
321			deps := scan.CheckDependenciesWithImages(cfg.Scan.TrivyImage, cfg.Scan.GitleaksImage)
322			tools = append(tools, shared.ToolInfo{
323				Name:      "Trivy",
324				Available: deps.TrivyAvailable,
325				Version:   cleanVersion(deps.TrivyVersion),
326				Source:    string(deps.TrivySource),
327			})
328			tools = append(tools, shared.ToolInfo{
329				Name:      "Gitleaks",
330				Available: deps.GitleaksAvailable,
331				Version:   cleanVersion(deps.GitleaksVersion),
332				Source:    string(deps.GitleaksSource),
333			})
334	
335			// Network Diagnostics image
336			tools = append(tools, detectDockerImage("Net Diag", cfg.Docker.NetworkToolImage))
337	
338			// Git
339			tools = append(tools, detectBinaryTool("Git", "git", "--version"))
340	
341			return ToolsDetectedMsg{Tools: tools}
342		}
343	}
344	
345	func (m Model) scheduleRefresh() tea.Cmd {
346		interval := m.refreshInterval
347		if interval < 10*time.Second {
348			interval = 30 * time.Second
349		}
350		return tea.Tick(interval, func(t time.Time) tea.Msg {
351			return RefreshTickMsg(t)
352		})
353	}
354	
355	func (m Model) refreshAll() tea.Cmd {
356		return tea.Batch(
357			m.checkServices(),
358			m.fetchGitLabStats(),
359			m.fetchDockerStats(),
360			m.fetchOCIStats(),
361			m.fetchWorkspaceStats(),
362			m.scheduleRefresh(),
363		)
364	}
365	
366	// computeGlobalStatus determines overall service health
367	func computeGlobalStatus(components []status.ComponentStatus) shared.ServiceGlobalStatus {
368		if len(components) == 0 {
369			return shared.ServiceStatusUnknown
370		}
371	
372		okCount := 0
373		for _, c := range components {
374			if c.Status == status.StatusOK {
375				okCount++
376			}
377		}
378	
379		if okCount == len(components) {
380			return shared.ServiceStatusAllOK
381		}
382		if okCount == 0 {
383			return shared.ServiceStatusDown
384		}
385		return shared.ServiceStatusDegraded
386	}
387	
388	// InEditMode returns false - dashboard has no edit modes
389	func (m Model) InEditMode() bool {
390		return false
391	}
392	
393	// detectDockerImage checks if a Docker image is available locally
394	func detectDockerImage(name, image string) shared.ToolInfo {
395		tool := shared.ToolInfo{Name: name, Version: image, Source: "image"}
396		cmd := exec.Command("docker", "image", "inspect", "--format", "{{.Id}}", image)
397		if err := cmd.Run(); err == nil {
398			tool.Available = true
399		}
400		return tool
401	}
402	
403	// detectBinaryTool checks if a binary is available and gets its version
404	func detectBinaryTool(name, binary string, versionArgs ...string) shared.ToolInfo {
405		tool := shared.ToolInfo{Name: name}
406	
407		if _, err := exec.LookPath(binary); err != nil {
408			return tool
409		}
410	
411		tool.Available = true
412		tool.Source = "binary"
413	
414		if len(versionArgs) > 0 {
415			cmd := exec.Command(binary, versionArgs...)
416			if out, err := cmd.Output(); err == nil {
417				tool.Version = cleanVersion(string(out))
418			}
419		}
420	
421		return tool
422	}
423	
424	// cleanVersion removes whitespace and "docker:" prefix from version strings
425	func cleanVersion(v string) string {
426		v = strings.TrimSpace(v)
427		v = strings.TrimPrefix(v, "docker:")
428		v = strings.TrimSpace(v)
429		// Take first line only
430		if idx := strings.IndexByte(v, '\n'); idx >= 0 {
