414	func (m *Model) handleKeyRunning(msg tea.KeyMsg) (*Model, tea.Cmd) {
415		if msg.String() != "esc" {
416			return m, nil
417		}
418		// Invalidate the current run so arriving testCompleteMsgs are discarded
419		m.runGen++
420		// Mark all non-done tests as cancelled
421		for _, name := range m.resultOrder {
422			if res := m.results[name]; !res.done {
423				m.results[name] = testResult{name: name, done: true, cancelled: true, output: "cancelled"}
424				m.doneTests++
425			}
426		}
427		m.state = StateResults
428		m.rebuildResultsTable()
429		return m, nil
430	}
431	
432	func (m *Model) handleKeyInput(msg tea.KeyMsg) (*Model, tea.Cmd) {
433		switch msg.String() {
434		case "down":
435			m.moveFocus(1)
436			return m, nil
437		case "up":
438			m.moveFocus(-1)
439			return m, nil
440		case "enter":
441			if m.focusedField == fieldButton {
442				return m.startTests()
443			}
444			return m, nil
445		case " ":
446			// Space is the only key that toggles checkboxes (Rule 135)
447			m.toggleFocusedCheckbox()
448			return m, nil
449		case "esc":
450			return m, nil
451		}
452	
453		// Forward to active text input
454		return m.updateActiveInput(msg)
455	}
456	
457	func (m *Model) moveFocus(delta int) {
458		// Blur current input if leaving a text field
459		switch m.focusedField {
460		case fieldTarget:
461			m.targetInput.Blur()
462		case fieldPort:
463			m.portInput.Blur()
464		case fieldDNSServer:
465			m.dnsServerInput.Blur()
466		}
467	
468		m.focusedField = (m.focusedField + delta + fieldCount) % fieldCount
469	
470		// Focus new input if entering a text field
471		switch m.focusedField {
472		case fieldTarget:
473			m.targetInput.Focus()
474		case fieldPort:
475			m.portInput.Focus()
476		case fieldDNSServer:
477			m.dnsServerInput.Focus()
478		}
479	}
480	
481	func (m *Model) toggleFocusedCheckbox() {
482		for i := range m.tests {
483			if m.tests[i].fieldIdx == m.focusedField {
484				m.tests[i].enabled = !m.tests[i].enabled
485				return
486			}
487		}
488	}
489	
490	func (m *Model) updateActiveInput(msg tea.KeyMsg) (*Model, tea.Cmd) {
491		var cmd tea.Cmd
492		switch m.focusedField {
493		case fieldTarget:
494			m.targetInput, cmd = m.targetInput.Update(msg)
495		case fieldPort:
496			m.portInput, cmd = m.portInput.Update(msg)
497		case fieldDNSServer:
498			m.dnsServerInput, cmd = m.dnsServerInput.Update(msg)
499		}
500		return m, cmd
501	}
502	
503	func (m *Model) handleKeyResults(msg tea.KeyMsg) (*Model, tea.Cmd) {
504		switch msg.String() {
505		case "enter":
506			return m.openDetails()
507		case "ctrl+r", "r":
508			return m.resetToForm()
509		case "up", "k":
510			m.resultsTable.MoveUp(1)
511		case "down", "j":
512			m.resultsTable.MoveDown(1)
513		case "g":
514			m.resultsTable.GotoTop()
515		case "G":
516			m.resultsTable.GotoBottom()
517		}
518		return m, nil
519	}
520	
521	func (m *Model) handleKeyDetails(msg tea.KeyMsg) (*Model, tea.Cmd) {
522		switch msg.String() {
523		case "esc":
524			m.state = StateResults
525			return m, nil
526		case "f":
527			m.rawDetails = !m.rawDetails
528			res := m.results[m.selectedTest]
529			m.detailsViewport.SetContent(m.renderDetailsContent(res, m.detailsViewport.Width))
530			m.detailsViewport.GotoTop()
531		case "up", "k":
532			m.detailsViewport.ScrollUp(1)
533		case "down", "j":
534			m.detailsViewport.ScrollDown(1)
535		case "pgup":
536			m.detailsViewport.HalfPageUp()
537		case "pgdown":
538			m.detailsViewport.HalfPageDown()
539		case "g":
540			m.detailsViewport.GotoTop()
541		case "G":
542			m.detailsViewport.GotoBottom()
543		}
544		return m, nil
545	}
546	
547	func (m *Model) openDetails() (*Model, tea.Cmd) {
548		idx := m.resultsTable.Cursor()
549		if idx < 0 || idx >= len(m.resultOrder) {
550			return m, nil
551		}
552		name := m.resultOrder[idx]
553		res, ok := m.results[name]
554		if !ok {
555			return m, nil
556		}
557		m.selectedTest = name
558		m.rawDetails = false
559		m.state = StateDetails
560		m.resizeDetailsViewport()
561		m.detailsViewport.SetContent(m.renderDetailsContent(res, m.detailsViewport.Width))
562		m.detailsViewport.GotoTop()
563		return m, nil
564	}
565	
566	func (m *Model) resetToForm() (*Model, tea.Cmd) {
567		m.state = StateInput
568		m.focusedField = fieldTarget
569		m.targetInput.Focus()
570		m.results = make(map[string]testResult)
571		m.doneTests = 0
572		m.totalTests = 0
