583	
584		port := strings.TrimSpace(m.portInput.Value())
585		if port == "" {
586			port = defaultPort
587		}
588		if err := validatePort(port); err != nil {
589			m.footerError = capitalize(err.Error())
590			return m, clearFooterCmd()
591		}
592	
593		enabled := m.enabledTests()
594		if len(enabled) == 0 {
595			m.footerError = "Select at least one test"
