601		m.state = StateRunning
602		m.results = make(map[string]testResult)
603		m.resultOrder = nil
604		m.doneTests = 0
605		m.totalTests = len(enabled)
606	
607		dnsServer := strings.TrimSpace(m.dnsServerInput.Value())
608		image := m.config.Docker.NetworkToolImage
609	
610		var cmds []tea.Cmd
611		cmds = append(cmds, m.spinner.Tick)
