621				cmd = runTestCmd(gen, name, func() dockerpkg.DiagResult {
622					return dockerpkg.RunPing(image, target)
623				})
624			case "DNS Resolution":
625				cmd = m.buildDNSTestCmd(gen, target, dnsServer, image)
626			case "Traceroute":
627				cmd = runTestCmd(gen, name, func() dockerpkg.DiagResult {
