678		}
679	
680		// It's a group - create directory and process children using slug
681		groupPath := filepath.Join(basePath, nodeSlug(node.FullPath))
682	
683		// Create directory
684		if err := os.MkdirAll(groupPath, 0755); err != nil {
685			report.Errors = append(report.Errors, fmt.Sprintf("mkdir %s: %v", groupPath, err))
686			return
