	// Fetch projects
	projectsOpts := &gitlabclient.ListGroupProjectsOptions{
		ListOptions: gitlabclient.ListOptions{
			PerPage: 100,
			Page:    1,
		},
	}
	projects, _, err := client.Groups.ListGroupProjects(groupID, projectsOpts)
	if err != nil {
		return nil, err
	}

	for _, project := range projects {
