	parentID := msg.ParentID

	return func() tea.Msg {
		// Use name as path (slug)
		path := strings.ToLower(strings.ReplaceAll(name, " ", "-"))

		group, err := gitlab.CreateGroup(client, name, path, description, visibility, parentID)
