23	type fakeGitLab struct {
24		server *httptest.Server
25		routes map[string]string
26		paths  []string
27	}
28	
29	func newFakeGitLab(t *testing.T, routes map[string]string) *fakeGitLab {
30		t.Helper()
31		f := &fakeGitLab{routes: routes}
32		f.server = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
33			f.paths = append(f.paths, r.URL.Path)
34			for prefix, body := range f.routes {
35				if strings.HasPrefix(r.URL.Path, prefix) {
36					w.Header().Set("Content-Type", "application/json")
37					_, _ = w.Write([]byte(body))
38					return
39				}
40			}
41			http.Error(w, `{"message":"404 Not Found"}`, http.StatusNotFound)
42		}))
43		t.Cleanup(f.server.Close)
44		return f
45	}
