// Rule 130: a shortcut for an action that cannot run here must not be
// advertised.
func TestShortcutsFollowTheState(t *testing.T) {
	tests := []struct {
		name    string
		open    func(*testing.T) Model
		want    []string
		notWant []string
	}{
		{
			name:    "the form",
