			want:    []string{"space", "←→", "enter / ctrl+s"},
			notWant: []string{"b", "tab", "i", "."},
		},
		{
			// 'b' opens a browser for the target, so it only means something
			// while the target field has focus.
			name: "the target field",
			open: func(t *testing.T) Model {
